package AppHooks;import factory.DriverFactory;import io.cucumber.java.After;import io.cucumber.java.Before;import io.cucumber.java.Scenario;import org.junit.Assume;import org.openqa.selenium.OutputType;import org.openqa.selenium.TakesScreenshot;import org.openqa.selenium.WebDriver;import util.ConfigReader;import java.util.Properties;// Cucumber hooks for test lifecycle. Loads configuration, starts browser and captures failure screenshots.public class ApplicationHooks {    private DriverFactory driverFactory;    private WebDriver driver;    private ConfigReader configReader;    Properties prop;    @Before(value="@Skip", order =0)    public void skipScenario(Scenario scenario) {        System.out.println("SKIPPED SCENARIO IS: " + scenario.getName());        Assume.assumeTrue(false); // This will skip the scenario    }    @Before(order = 1)    public void getProperty() {        configReader = new ConfigReader();        prop = configReader.init_prop();    }    @Before(order = 2)    public void launchBrowser() {        String browserName = prop.getProperty("browser");        driverFactory = new DriverFactory();        driver = driverFactory.init_driver(browserName);        //driver.get(prop.getProperty("url")); // consider using config for base URL    }    // Important: ensure screenshot (order=0) runs BEFORE quitBrowser to capture failures successfully.    @After(order = 0)    public void tearDown(Scenario scenario) {        if (scenario.isFailed()) {            // take screenshot and attach to report            String screenshotName = scenario.getName().replaceAll(" ", "_");            byte[] sourcePath = ((TakesScreenshot) driver).getScreenshotAs(OutputType.BYTES);            scenario.attach(sourcePath, "image/png", screenshotName);        }    }    @After(order = 1)    public void quitBrowser() {        if (driver != null) {            driver.quit();        }    }}